package com.purchasing;
import com.purchasing.agent.PurchasingAgent; import com.purchasing.dto.ReviewResponse; import com.purchasing.entity.*; import com.purchasing.repository.RecommendationRepository; import com.purchasing.service.PurchaseOrderService; import org.junit.jupiter.api.*; import org.springframework.beans.factory.annotation.*; import org.springframework.boot.test.context.SpringBootTest; import java.util.*; import static org.junit.jupiter.api.Assertions.*;
@SpringBootTest class PurchasingAgentApplicationTests { @Autowired PurchasingAgent agent; @Autowired RecommendationRepository recommendations; @Autowired PurchaseOrderService orders; @Test void modifyScenarioCreatesValidatedPo(){ReviewResponse r=agent.review(1L);assertEquals("MODIFIED",r.decision());assertTrue(r.actionTaken());assertEquals("PASSED",r.validationStatus());} @Test void acceptsFeasibleRecommendation(){ReviewResponse r=agent.review(2L);assertEquals("ACCEPTED",r.decision());} @Test void rejectsWhenNoSpace(){ReviewResponse r=agent.review(3L);assertEquals("INVESTIGATED_FURTHER",r.decision());assertTrue(r.humanApprovalRequired());} @Test void validationFailureMarksOrderForReview(){PurchaseRecommendation r=recommendations.findById(2L).orElseThrow();PurchaseOrder po=orders.create(r.product,r.supplier,50);Map<String,Object> result=orders.validate(po);assertEquals("FAILED",result.get("status"));assertEquals("REVIEW_REQUIRED",orders.get(po.id).status);} }
